-- Упражнения книги 19, глава 19 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-exports-access', 0, 'func', 'Доступ по /etc/exports', 'Напишите функцию export_access(text, path, client, uid): text - содержимое /etc/exports, path - путь, который клиент хочет смонтировать, client - словарь {''name'': полное имя, ''ip'': IPv4-адрес, ''netgroups'': список имён групп, в которые клиент входит}, uid - пользователь на клиенте. Верните кортеж (режим, uid на сервере) или None, если доступа нет. Формат файла: комментарий - от # до конца строки (уберите его в каждой физической строке); строка, оканчивающаяся на \ (после удаления комментария), продолжается на следующей; пустые строки пропускаются. Строка - путь экспорта и клиенты через пробелы; у клиента сразу за именем может стоять ''(опции,через,запятую)''. Для пути применяется экспорт с самым длинным путём, который равен path или является его родителем по границе компонента (''/'' - родитель любого пути); строки с одним и тем же путём экспорта объединяются в порядке файла. Из клиентов этого экспорта выбирается самый точный подходящий тип, независимо от порядка строк: 0 - один хост (имя без регистра, или IP-адрес клиента, или короткое имя без точек, равное первой метке имени клиента), 1 - сеть ''адрес/маска'' (длина или десятичная маска, host-биты игнорируются), 2 - шаблон с * ? [ ] (сравнивается с именем клиента без регистра, * совпадает и с точками, к IP шаблоны не применяются), 3 - ''@группа'' (клиент входит в группу), 4 - ровно ''*''. Внутри одного типа побеждает первый по порядку. Опции: ro или rw (по умолчанию ro; последняя побеждает), root_squash или no_root_squash (по умолчанию root_squash), all_squash или no_all_squash, anonuid=N (по умолчанию 65534); остальные опции игнорируются. Серверный uid: anonuid, если включён all_squash или (uid равен 0 и действует root_squash), иначе uid клиента.', 'def export_access(text, path, client, uid):
    pass
', 'Сначала склейте строки и разберите их на (путь, клиент, опции); затем выберите экспорт по пути и пройдите клиентов, запоминая лучший тип и опции.', '{"func": "export_access", "tests": [{"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/ovirt/data", {"name": "kvm1.virt.example.com", "ip": "10.0.5.11", "netgroups": ["hypervisors"]}, 0], "expected": {"__tuple__": ["rw", 0]}}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/ovirt/data", {"name": "kvm2.virt.example.com", "ip": "10.0.9.20", "netgroups": []}, 0], "expected": {"__tuple__": ["rw", 36]}}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/ovirt/data/images/1", {"name": "kvm2.virt.example.com", "ip": "10.0.9.20", "netgroups": []}, 1000], "expected": {"__tuple__": ["rw", 36]}}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/ovirt/data", {"name": "laptop.corp.example.org", "ip": "192.168.0.77", "netgroups": []}, 36], "expected": null}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/ovirt/iso", {"name": "kvm1.virt.example.com", "ip": "10.0.5.11", "netgroups": ["hypervisors"]}, 0], "expected": {"__tuple__": ["ro", 65534]}}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/ovirt/iso", {"name": "kvm3.virt.example.com", "ip": "10.0.5.12", "netgroups": ["hypervisors"]}, 0], "expected": {"__tuple__": ["rw", 65534]}}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/ovirt/iso", {"name": "kvm2.virt.example.com", "ip": "10.0.9.20", "netgroups": []}, 5], "expected": null}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/public", {"name": "laptop.corp.example.org", "ip": "192.168.0.77", "netgroups": []}, 1000], "expected": {"__tuple__": ["ro", 1001]}}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/home", {"name": "laptop.corp.example.org", "ip": "192.168.0.77", "netgroups": []}, 0], "expected": {"__tuple__": ["rw", 65534]}}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/home", {"name": "ADMIN1", "ip": "172.16.0.5", "netgroups": []}, 0], "expected": {"__tuple__": ["rw", 0]}}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/home", {"name": "kvm2.virt.example.com", "ip": "10.0.9.20", "netgroups": []}, 0], "expected": {"__tuple__": ["ro", 65534]}}, {"args": ["# oVirt storage and friends\n/srv/ovirt/data  *.virt.example.com(rw,sync,no_subtree_check,all_squash,anonuid=36,anongid=36) \\\n                 10.0.5.0/24(rw,sync,no_root_squash)   # the management network\n/srv/ovirt/iso   @hypervisors(ro) 10.0.5.12(rw)\n/srv/public      *(ro,all_squash,anonuid=1001)\n\n/srv/home        192.168.0.0/255.255.255.0(rw)\n/srv/home        admin1(rw,no_root_squash) *(ro)\n", "/srv/ovirtx", {"name": "kvm1.virt.example.com", "ip": "10.0.5.11", "netgroups": ["hypervisors"]}, 0], "expected": null}, {"args": ["/              kvm1(rw) 10.0.0.0/8(ro,no_root_squash)\n/srv           *.example.com(rw,anonuid=500)\n/srv/backup    backup[0-9].example.com(rw,no_root_squash,anonuid=34)\n/srv/scratch   *(rw,sync,no_subtree_check,fsid=7,all_squash)\n", "/etc", {"name": "kvm1.virt.example.com", "ip": "10.0.5.11", "netgroups": ["hypervisors"]}, 0], "expected": {"__tuple__": ["rw", 65534]}}, {"args": ["/              kvm1(rw) 10.0.0.0/8(ro,no_root_squash)\n/srv           *.example.com(rw,anonuid=500)\n/srv/backup    backup[0-9].example.com(rw,no_root_squash,anonuid=34)\n/srv/scratch   *(rw,sync,no_subtree_check,fsid=7,all_squash)\n", "/etc", {"name": "kvm1", "ip": "10.7.7.7", "netgroups": []}, 0], "expected": {"__tuple__": ["rw", 65534]}}, {"args": ["/              kvm1(rw) 10.0.0.0/8(ro,no_root_squash)\n/srv           *.example.com(rw,anonuid=500)\n/srv/backup    backup[0-9].example.com(rw,no_root_squash,anonuid=34)\n/srv/scratch   *(rw,sync,no_subtree_check,fsid=7,all_squash)\n", "/srv/backup/db", {"name": "backup3.example.com", "ip": "192.0.2.33", "netgroups": []}, 0], "expected": {"__tuple__": ["rw", 0]}}, {"args": ["/              kvm1(rw) 10.0.0.0/8(ro,no_root_squash)\n/srv           *.example.com(rw,anonuid=500)\n/srv/backup    backup[0-9].example.com(rw,no_root_squash,anonuid=34)\n/srv/scratch   *(rw,sync,no_subtree_check,fsid=7,all_squash)\n", "/srv/backup", {"name": "kvm1.virt.example.com", "ip": "10.0.5.11", "netgroups": ["hypervisors"]}, 0], "expected": null}, {"args": ["/              kvm1(rw) 10.0.0.0/8(ro,no_root_squash)\n/srv           *.example.com(rw,anonuid=500)\n/srv/backup    backup[0-9].example.com(rw,no_root_squash,anonuid=34)\n/srv/scratch   *(rw,sync,no_subtree_check,fsid=7,all_squash)\n", "/srv/scratch", {"name": "laptop.corp.example.org", "ip": "192.168.0.77", "netgroups": []}, 77], "expected": {"__tuple__": ["rw", 65534]}}, {"args": ["/              kvm1(rw) 10.0.0.0/8(ro,no_root_squash)\n/srv           *.example.com(rw,anonuid=500)\n/srv/backup    backup[0-9].example.com(rw,no_root_squash,anonuid=34)\n/srv/scratch   *(rw,sync,no_subtree_check,fsid=7,all_squash)\n", "/srv/other", {"name": "kvm2.virt.example.com", "ip": "10.0.9.20", "netgroups": []}, 0], "expected": {"__tuple__": ["rw", 500]}}, {"args": ["", "/srv", {"name": "kvm1.virt.example.com", "ip": "10.0.5.11", "netgroups": ["hypervisors"]}, 0], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-exportfs-audit', 1, 'func', 'Аудит вывода exportfs -v', 'text - вывод exportfs -v. Каждый экспорт - это путь и клиент с опциями в скобках: ''путь<табуляция>клиент(опции)'', а если путь длиннее 14 символов, то ''путь'', перевод строки, две табуляции и ''клиент(опции)''. Клиент без ограничений печатается как <world>. Напишите функцию audit(text): верните список [путь, клиент, код] в порядке записей; для одной записи коды идут по алфавиту. Коды: ''async'' (в опциях есть async), ''insecure'' (есть insecure), ''root-open'' (есть no_root_squash, а клиент не один хост: это <world>, сеть с /, шаблон с * ? [ или группа @имя), ''rw-world'' (клиент <world> и есть rw), ''subtree-check'' (в опциях нет no_subtree_check: при включённой проверке exportfs этот токен не печатает). Опции сравнивайте по целым токенам. Пустые строки пропускайте.', 'def audit(text):
    pass
', 'Строка без отступа начинает новый путь (после пути может сразу идти клиент); строка с отступом - клиент прежнего пути. Опции - между первой ''('' и последней '')''.', '{"func": "audit", "tests": [{"args": ["/srv/ovirt/data\n\t\t10.0.5.0/24(sync,wdelay,hide,no_subtree_check,sec=sys,rw,secure,no_root_squash,no_all_squash)\n/srv/ovirt/data\n\t\t*.virt.example.com(sync,wdelay,hide,no_subtree_check,anonuid=36,anongid=36,sec=sys,rw,secure,root_squash,all_squash)\n/srv/ovirt/iso\t@hypervisors(sync,wdelay,hide,no_subtree_check,sec=sys,ro,secure,root_squash,no_all_squash)\n/srv/ovirt/iso\tkvm3.virt.example.com(sync,wdelay,hide,no_subtree_check,sec=sys,ro,secure,root_squash,no_all_squash)\n"], "expected": [["/srv/ovirt/data", "10.0.5.0/24", "root-open"]]}, {"args": ["/srv/public   \t<world>(sync,wdelay,hide,no_subtree_check,sec=sys,ro,secure,root_squash,no_all_squash)\n/srv/scratch  \t<world>(async,wdelay,hide,no_subtree_check,sec=sys,rw,secure,no_root_squash,no_all_squash)\n/srv/ovirt/data\n\t\t10.0.0.0/8(sync,wdelay,hide,no_subtree_check,sec=sys,rw,insecure,no_root_squash,no_all_squash)\n/srv/ovirt/data\n\t\tkvm1(sync,wdelay,hide,no_subtree_check,sec=sys,rw,secure,no_root_squash,no_all_squash)\n"], "expected": [["/srv/scratch", "<world>", "async"], ["/srv/scratch", "<world>", "root-open"], ["/srv/scratch", "<world>", "rw-world"], ["/srv/ovirt/data", "10.0.0.0/8", "insecure"], ["/srv/ovirt/data", "10.0.0.0/8", "root-open"]]}, {"args": ["/home         \tbackup1.example.com(async,wdelay,hide,sec=sys,rw,secure,root_squash,no_all_squash)\n/srv/db       \t*(sync,wdelay,hide,sec=sys,rw,secure,no_root_squash,no_all_squash)\n/mnt          \t@trusted(sync,wdelay,hide,no_subtree_check,fsid=0,crossmnt,sec=sys,rw,insecure,root_squash,no_all_squash)\n"], "expected": [["/home", "backup1.example.com", "async"], ["/home", "backup1.example.com", "subtree-check"], ["/srv/db", "*", "root-open"], ["/srv/db", "*", "subtree-check"], ["/mnt", "@trusted", "insecure"]]}, {"args": ["/srv/x        \t192.0.2.5(sync,wdelay,hide,no_subtree_check,sec=sys,ro,secure,root_squash,no_all_squash)\n"], "expected": []}, {"args": [""], "expected": []}, {"args": ["/srv/ovirt/data\n\t\t10.0.5.0/24(sync,wdelay,hide,no_subtree_check,sec=sys,rw,secure,no_root_squash,no_all_squash)\n/srv/ovirt/data\n\t\t*.virt.example.com(sync,wdelay,hide,no_subtree_check,anonuid=36,anongid=36,sec=sys,rw,secure,root_squash,all_squash)\n/srv/ovirt/iso\t@hypervisors(sync,wdelay,hide,no_subtree_check,sec=sys,ro,secure,root_squash,no_all_squash)\n/srv/ovirt/iso\tkvm3.virt.example.com(sync,wdelay,hide,no_subtree_check,sec=sys,ro,secure,root_squash,no_all_squash)\n/srv/x        \t192.0.2.5(sync,wdelay,hide,no_subtree_check,sec=sys,ro,secure,root_squash,no_all_squash)\n"], "expected": [["/srv/ovirt/data", "10.0.5.0/24", "root-open"]]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-fstab-nfs', 2, 'func', 'Строки NFS в fstab', 'Напишите функцию check_fstab(text): text - /etc/fstab. Строки-комментарии (первый непробельный символ #) и пустые пропускайте; поля разделяются пробелами или табуляциями. Строка считается строкой NFS, если первое поле содержит '':/'' или третье поле равно nfs или nfs4; остальные строки игнорируйте. Для строки NFS верните пары [номер строки (с 1), код] в порядке строк, а для одной строки - в порядке этого списка. ''fields'': полей не от 4 до 6 (других проверок для строки нет); ''type'': третье поле не nfs и не nfs4; ''spec'': первое поле не ''хост:/путь'' (хост - имя из букв, цифр, точек и дефисов, начинающееся с буквы или цифры, или IPv6 в квадратных скобках; путь начинается с /); ''nfs4-vers'': тип nfs4, а в опциях есть vers или nfsvers (с любым значением); ''hard-soft'': вместе hard и (soft или softerr); ''bad-number'': timeo, retrans, rsize или wsize не с целым числом больше нуля (один раз на строку); ''passno'': есть шестое поле и оно не 0; ''soft-rw'': есть soft или softerr, а ro нет. Имена опций сравнивайте по части до ''=''.', 'def check_fstab(text):
    pass
', 'Разбейте строку split(); проверки идут в заданном порядке, ''fields'' прекращает разбор строки.', '{"func": "check_fstab", "tests": [{"args": ["# /etc/fstab\nUUID=3f1a2b4c-0d5e-4f60-9a71-b2c3d4e5f607 /     ext4  defaults        0 1\nUUID=aa11bb22-cc33-dd44-ee55-ff6677889900 /boot xfs   defaults        0 2\nnfs1.example.com:/srv/ovirt/data  /rhev/data  nfs  defaults,_netdev  0 0\nnfs1.example.com:/srv/ovirt/iso   /mnt/iso    nfs4 ro,sec=sys,hard   0 0\n"], "expected": []}, {"args": ["nfs1:/export/home      /home     nfs   soft,timeo=100,retrans=3  0 0\nnfs1:/export/ro        /data     nfs   soft,ro,timeo=600         0 0\nnfs1:data              /mnt/a    nfs   defaults                  0 0\nnfs1:/x                /mnt/b    nfs4  vers=4.1,hard             0 0\nnfs1:/y                /mnt/c    nfs   hard,soft                 0 0\nnfs1:/z                /mnt/d    nfs   timeo=0,retrans=x,rsize=65536  0 2\n"], "expected": [[1, "soft-rw"], [3, "spec"], [4, "nfs4-vers"], [5, "hard-soft"], [5, "soft-rw"], [6, "bad-number"], [6, "passno"]]}, {"args": ["nfs1:/srv/a /mnt/a nfs\nnfs1:/srv/b /mnt/b nfs defaults\n[fe80::215:c5ff:fb3e:e2b1%eth0]:/export /mnt/c nfs defaults 0 0\nnfs1:/srv/e /mnt/e ext4 defaults 0 0\n//srv/f /mnt/f cifs ro 0 0\nsrv-g /mnt/g nfs defaults 0 0\nnfs1:/srv/h\t/mnt/h\tnfs\thard,nofail,bg\t0\t0\nnfs1:/srv/i /mnt/i nfs defaults 0 0 extra\n"], "expected": [[1, "fields"], [4, "type"], [6, "spec"], [8, "fields"]]}, {"args": [""], "expected": []}, {"args": ["# only a comment\n\n"], "expected": []}, {"args": ["# /etc/fstab\nUUID=3f1a2b4c-0d5e-4f60-9a71-b2c3d4e5f607 /     ext4  defaults        0 1\nUUID=aa11bb22-cc33-dd44-ee55-ff6677889900 /boot xfs   defaults        0 2\nnfs1.example.com:/srv/ovirt/data  /rhev/data  nfs  defaults,_netdev  0 0\nnfs1.example.com:/srv/ovirt/iso   /mnt/iso    nfs4 ro,sec=sys,hard   0 0\nnfs1:/export/home      /home     nfs   soft,timeo=100,retrans=3  0 0\nnfs1:/export/ro        /data     nfs   soft,ro,timeo=600         0 0\nnfs1:data              /mnt/a    nfs   defaults                  0 0\nnfs1:/x                /mnt/b    nfs4  vers=4.1,hard             0 0\nnfs1:/y                /mnt/c    nfs   hard,soft                 0 0\nnfs1:/z                /mnt/d    nfs   timeo=0,retrans=x,rsize=65536  0 2\n"], "expected": [[6, "soft-rw"], [8, "spec"], [9, "nfs4-vers"], [10, "hard-soft"], [10, "soft-rw"], [11, "bad-number"], [11, "passno"]]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-info-chain', 3, 'func', 'Цепочка из qemu-img info', 'text - вывод ''qemu-img info --backing-chain --output=json'' (JSON-массив объектов от верхнего образа к базовому) либо ''qemu-img info --output=json'' (один объект). Напишите функцию chain_report(text): верните словарь {''depth'': число образов, ''images'': список [имя файла без каталога, format, virtual-size, actual-size (0, если ключа нет)] сверху вниз, ''total_actual'': сумма actual-size, ''issues'': отсортированный список строк ''код:имя''}. Коды: ''no-backing-format'' (у образа есть backing-filename, но нет backing-filename-format); ''dirty'' (dirty-flag равен true); ''corrupt'' (format-specific.data.corrupt равен true); ''broken-link'' (образ не последний, а его backing-filename без каталога не совпадает с именем следующего образа или отсутствует); ''shrunk'' (звено целое, но virtual-size следующего образа больше, чем у этого); ''not-expanded'' (последний образ вывода всё ещё имеет backing-filename). Имена - последняя компонента пути. Каждый код для образа не более одного раза.', 'def chain_report(text):
    pass
', 'json.loads, затем один проход по образам; если разобрана не список, оберните объект в список.', '{"func": "chain_report", "tests": [{"args": ["[\n    {\n        \"virtual-size\": 21474836480,\n        \"filename\": \"/var/lib/images/vm1-snap2.qcow2\",\n        \"cluster-size\": 65536,\n        \"format\": \"qcow2\",\n        \"actual-size\": 3211264,\n        \"format-specific\": {\n            \"type\": \"qcow2\",\n            \"data\": {\n                \"compat\": \"1.1\",\n                \"compression-type\": \"zlib\",\n                \"lazy-refcounts\": false,\n                \"refcount-bits\": 16,\n                \"corrupt\": false,\n                \"extended-l2\": false\n            }\n        },\n        \"dirty-flag\": false,\n        \"backing-filename\": \"vm1-snap1.qcow2\",\n        \"full-backing-filename\": \"/var/lib/images/vm1-snap1.qcow2\",\n        \"backing-filename-format\": \"qcow2\"\n    },\n    {\n        \"virtual-size\": 21474836480,\n        \"filename\": \"/var/lib/images/vm1-snap1.qcow2\",\n        \"cluster-size\": 65536,\n        \"format\": \"qcow2\",\n        \"actual-size\": 1572864000,\n        \"format-specific\": {\n            \"type\": \"qcow2\",\n            \"data\": {\n                \"compat\": \"1.1\",\n                \"compression-type\": \"zlib\",\n                \"lazy-refcounts\": false,\n                \"refcount-bits\": 16,\n                \"corrupt\": false,\n                \"extended-l2\": false\n            }\n        },\n        \"dirty-flag\": false,\n        \"backing-filename\": \"base.raw\",\n        \"full-backing-filename\": \"/var/lib/images/base.raw\",\n        \"backing-filename-format\": \"raw\"\n    },\n    {\n        \"virtual-size\": 21474836480,\n        \"filename\": \"/var/lib/images/base.raw\",\n        \"format\": \"raw\",\n        \"actual-size\": 4307550208\n    }\n]"], "expected": {"depth": 3, "images": [["vm1-snap2.qcow2", "qcow2", 21474836480, 3211264], ["vm1-snap1.qcow2", "qcow2", 21474836480, 1572864000], ["base.raw", "raw", 21474836480, 4307550208]], "total_actual": 5883625472, "issues": []}}, {"args": ["[\n    {\n        \"virtual-size\": 10737418240,\n        \"filename\": \"top.qcow2\",\n        \"cluster-size\": 65536,\n        \"format\": \"qcow2\",\n        \"actual-size\": 209715200,\n        \"format-specific\": {\n            \"type\": \"qcow2\",\n            \"data\": {\n                \"compat\": \"1.1\",\n                \"compression-type\": \"zlib\",\n                \"lazy-refcounts\": false,\n                \"refcount-bits\": 16,\n                \"corrupt\": false,\n                \"extended-l2\": false\n            }\n        },\n        \"dirty-flag\": true,\n        \"backing-filename\": \"mid.qcow2\",\n        \"full-backing-filename\": \"mid.qcow2\"\n    },\n    {\n        \"virtual-size\": 42949672960,\n        \"filename\": \"mid.qcow2\",\n        \"cluster-size\": 65536,\n        \"format\": \"qcow2\",\n        \"actual-size\": 838860800,\n        \"format-specific\": {\n            \"type\": \"qcow2\",\n            \"data\": {\n                \"compat\": \"1.1\",\n                \"compression-type\": \"zlib\",\n                \"lazy-refcounts\": false,\n                \"refcount-bits\": 16,\n                \"corrupt\": true,\n                \"extended-l2\": false\n            }\n        },\n        \"dirty-flag\": false,\n        \"backing-filename\": \"base.qcow2\",\n        \"full-backing-filename\": \"base.qcow2\",\n        \"backing-filename-format\": \"qcow2\"\n    },\n    {\n        \"virtual-size\": 42949672960,\n        \"filename\": \"base.qcow2\",\n        \"cluster-size\": 65536,\n        \"format\": \"qcow2\",\n        \"actual-size\": 2147483648,\n        \"format-specific\": {\n            \"type\": \"qcow2\",\n            \"data\": {\n                \"compat\": \"1.1\",\n                \"compression-type\": \"zlib\",\n                \"lazy-refcounts\": false,\n                \"refcount-bits\": 16,\n                \"corrupt\": false,\n                \"extended-l2\": false\n            }\n        },\n        \"dirty-flag\": false\n    }\n]"], "expected": {"depth": 3, "images": [["top.qcow2", "qcow2", 10737418240, 209715200], ["mid.qcow2", "qcow2", 42949672960, 838860800], ["base.qcow2", "qcow2", 42949672960, 2147483648]], "total_actual": 3196059648, "issues": ["corrupt:mid.qcow2", "dirty:top.qcow2", "no-backing-format:top.qcow2", "shrunk:top.qcow2"]}}, {"args": ["{\n    \"virtual-size\": 8589934592,\n    \"filename\": \"/images/vm.qcow2\",\n    \"cluster-size\": 65536,\n    \"format\": \"qcow2\",\n    \"actual-size\": 196608,\n    \"format-specific\": {\n        \"type\": \"qcow2\",\n        \"data\": {\n            \"compat\": \"1.1\",\n            \"compression-type\": \"zlib\",\n            \"lazy-refcounts\": false,\n            \"refcount-bits\": 16,\n            \"corrupt\": false,\n            \"extended-l2\": false\n        }\n    },\n    \"dirty-flag\": false\n}"], "expected": {"depth": 1, "images": [["vm.qcow2", "qcow2", 8589934592, 196608]], "total_actual": 196608, "issues": []}}, {"args": ["{\n    \"virtual-size\": 8589934592,\n    \"filename\": \"/images/vm-top.qcow2\",\n    \"cluster-size\": 65536,\n    \"format\": \"qcow2\",\n    \"actual-size\": 262144,\n    \"format-specific\": {\n        \"type\": \"qcow2\",\n        \"data\": {\n            \"compat\": \"1.1\",\n            \"compression-type\": \"zlib\",\n            \"lazy-refcounts\": false,\n            \"refcount-bits\": 16,\n            \"corrupt\": false,\n            \"extended-l2\": false\n        }\n    },\n    \"dirty-flag\": false,\n    \"backing-filename\": \"/images/vm-base.qcow2\",\n    \"full-backing-filename\": \"/images/vm-base.qcow2\",\n    \"backing-filename-format\": \"qcow2\"\n}"], "expected": {"depth": 1, "images": [["vm-top.qcow2", "qcow2", 8589934592, 262144]], "total_actual": 262144, "issues": ["not-expanded:vm-top.qcow2"]}}, {"args": ["[\n    {\n        \"virtual-size\": 1073741824,\n        \"filename\": \"a.qcow2\",\n        \"cluster-size\": 65536,\n        \"format\": \"qcow2\",\n        \"actual-size\": 1048576,\n        \"format-specific\": {\n            \"type\": \"qcow2\",\n            \"data\": {\n                \"compat\": \"1.1\",\n                \"compression-type\": \"zlib\",\n                \"lazy-refcounts\": false,\n                \"refcount-bits\": 16,\n                \"corrupt\": false,\n                \"extended-l2\": false\n            }\n        },\n        \"dirty-flag\": false,\n        \"backing-filename\": \"b.qcow2\",\n        \"full-backing-filename\": \"b.qcow2\",\n        \"backing-filename-format\": \"qcow2\"\n    },\n    {\n        \"virtual-size\": 1073741824,\n        \"filename\": \"c.qcow2\",\n        \"cluster-size\": 65536,\n        \"format\": \"qcow2\",\n        \"actual-size\": 5242880,\n        \"format-specific\": {\n            \"type\": \"qcow2\",\n            \"data\": {\n                \"compat\": \"1.1\",\n                \"compression-type\": \"zlib\",\n                \"lazy-refcounts\": false,\n                \"refcount-bits\": 16,\n                \"corrupt\": false,\n                \"extended-l2\": false\n            }\n        },\n        \"dirty-flag\": false\n    }\n]"], "expected": {"depth": 2, "images": [["a.qcow2", "qcow2", 1073741824, 1048576], ["c.qcow2", "qcow2", 1073741824, 5242880]], "total_actual": 6291456, "issues": ["broken-link:a.qcow2"]}}, {"args": ["{\n    \"virtual-size\": 5368709120,\n    \"filename\": \"disk.raw\",\n    \"format\": \"raw\",\n    \"actual-size\": 0\n}"], "expected": {"depth": 1, "images": [["disk.raw", "raw", 5368709120, 0]], "total_actual": 0, "issues": []}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-read-source', 4, 'func', 'Откуда читается кластер', 'Цепочка образов qcow2 описана списком layers от верхнего образа к базовому: [имя, virtual_size в байтах, ranges]. ranges - строка из элементов через запятую: ''N'' (кластер N), ''A-B'' (кластеры от A до B включительно), с необязательной буквой z на конце (''4z'', ''6-9z''): такой кластер выделен как нулевой. Позднее упоминание кластера в той же строке заменяет раннее; пустая строка - ничего не выделено. Кластер выделен в образе, только если его начало (номер * cluster_size) меньше virtual_size этого образа. Напишите функцию read_sources(layers, cluster_size, offsets): для каждого смещения гостя верните имя первого образа сверху, где кластер offset // cluster_size выделен с данными; ''zeros'', если первым найден нулевой кластер или кластера нет ни в одном образе; ''out-of-range'', если смещение отрицательное или не меньше virtual_size верхнего образа.', 'def read_sources(layers, cluster_size, offsets):
    pass
', 'Разберите ranges в словарь кластер -> ''data''/''zero'' для каждого образа, затем для каждого смещения идите сверху вниз до первого образа, где кластер есть.', '{"func": "read_sources", "tests": [{"args": [[["top", 1048576, "0,3"], ["mid", 1048576, "1-2,4z"], ["base", 524288, "0-7"]], 65536, [0, 65535, 65536, 196608, 262144, 458752, 524288, 983040, 1048576]], "expected": ["top", "top", "mid", "top", "zeros", "base", "zeros", "zeros", "out-of-range"]}, {"args": [[["top", 262144, "2z"], ["base", 262144, "0-3"]], 65536, [0, 131077, 196608]], "expected": ["base", "zeros", "base"]}, {"args": [[["only", 131072, ""]], 4096, [0, 131071, 131072, -1]], "expected": ["zeros", "zeros", "out-of-range", "out-of-range"]}, {"args": [[["t", 40960, "1-2,2z"], ["b", 40960, "0-9"]], 4096, [4096, 8192, 12288, 40959]], "expected": ["t", "zeros", "b", "b"]}, {"args": [[["t", 100000, "0-30"], ["b", 100000, ""]], 4096, [99999, 98305, 100000]], "expected": ["t", "t", "out-of-range"]}, {"args": [[["s", 393216, "0-5"], ["b", 131072, "0-1"]], 65536, [0, 393215]], "expected": ["s", "s"]}, {"args": [[["big", 524288, ""], ["small", 196608, "0-7"]], 65536, [0, 131072, 196608, 458752]], "expected": ["small", "small", "zeros", "zeros"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-commit-rebase', 5, 'func', 'commit и rebase на модели цепочки', 'Образ - слой [имя, backing (имя или None), данные: список пар [кластер, значение]]; значение - метка данных (0 - явно нулевой выделенный кластер). Вид гостя образа X - список из n значений для кластеров 0..n-1: для каждого кластера берётся значение первого слоя в цепочке X, backing X, ... , где кластер выделен, а если такого слоя нет - 0. Напишите функцию chain_ops(layers, ops, image, n): выполните операции по порядку и верните {''view'': вид гостя образа image, ''alloc'': {имя слоя: отсортированный список выделенных кластеров}} для всех слоёв. Операции: [''write'', имя, кластер, значение] - записать в слой; [''commit'', имя] - как ''qemu-img commit'': все кластеры слоя записываются в его backing (с заменой), слой становится пустым, но остаётся связан с backing (если backing нет - операция пропускается); [''rebase'', имя, новый_backing или None, ''safe''|''unsafe''] - как ''qemu-img rebase -b'' и ''rebase -u -b'': в безопасном режиме для каждого кластера 0..n-1, который не выделен в слое, а в виде гостя прежнего backing (None - все нули) значение отличается от вида нового backing (None - все нули), в слой копируется значение прежнего вида (в том числе 0); затем (в обоих режимах) backing слоя заменяется на новый.', 'def chain_ops(layers, ops, image, n):
    pass
', 'Храните слои в словаре имя -> [backing, {кластер: значение}], а вид считайте функцией view(имя), идущей вниз по backing.', '{"func": "chain_ops", "tests": [{"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [], "top", 6], "expected": {"view": [4, 2, 3, 1, 4, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [1, 4], "snap2": [2], "top": [0, 4]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [["commit", "top"]], "top", 6], "expected": {"view": [4, 2, 3, 1, 4, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [1, 4], "snap2": [0, 2, 4], "top": []}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [["commit", "top"]], "snap2", 6], "expected": {"view": [4, 2, 3, 1, 4, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [1, 4], "snap2": [0, 2, 4], "top": []}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [["commit", "snap2"], ["commit", "snap1"]], "top", 6], "expected": {"view": [4, 2, 3, 1, 4, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [], "snap2": [], "top": [0, 4]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [["rebase", "top", "snap1", "safe"]], "top", 6], "expected": {"view": [4, 2, 3, 1, 4, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [1, 4], "snap2": [2], "top": [0, 2, 4]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [["rebase", "top", "snap1", "unsafe"]], "top", 6], "expected": {"view": [4, 2, 1, 1, 4, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [1, 4], "snap2": [2], "top": [0, 4]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [["rebase", "top", "base", "safe"]], "top", 6], "expected": {"view": [4, 2, 3, 1, 4, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [1, 4], "snap2": [2], "top": [0, 1, 2, 4]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [["rebase", "top", null, "safe"]], "top", 6], "expected": {"view": [4, 2, 3, 1, 4, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [1, 4], "snap2": [2], "top": [0, 1, 2, 3, 4, 5]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [["write", "top", 5, 8], ["commit", "top"], ["write", "top", 0, 5]], "top", 6], "expected": {"view": [5, 2, 3, 1, 4, 8], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [1, 4], "snap2": [0, 2, 4, 5], "top": [0]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["snap1", "base", [[1, 2], [4, 2]]], ["snap2", "snap1", [[2, 3]]], ["top", "snap2", [[0, 4], [4, 4]]]], [["commit", "base"]], "base", 6], "expected": {"view": [1, 1, 1, 1, 1, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "snap1": [1, 4], "snap2": [2], "top": [0, 4]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["other", null, [[0, 9], [3, 9], [5, 9]]], ["top", "base", [[1, 7]]]], [["rebase", "top", "other", "safe"]], "top", 6], "expected": {"view": [1, 7, 1, 1, 1, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "other": [0, 3, 5], "top": [0, 1, 2, 3, 4, 5]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["other", null, [[0, 9], [3, 9], [5, 9]]], ["top", "base", [[1, 7]]]], [["rebase", "top", "other", "unsafe"]], "top", 6], "expected": {"view": [9, 7, 0, 9, 0, 9], "alloc": {"base": [0, 1, 2, 3, 4, 5], "other": [0, 3, 5], "top": [1]}}}, {"args": [[["base", null, [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1], [5, 1]]], ["other", null, [[0, 9], [3, 9], [5, 9]]], ["top", "base", [[1, 7]]]], [["write", "top", 3, 0], ["rebase", "top", "other", "safe"]], "top", 6], "expected": {"view": [1, 7, 1, 0, 1, 1], "alloc": {"base": [0, 1, 2, 3, 4, 5], "other": [0, 3, 5], "top": [0, 1, 2, 3, 4, 5]}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-measure-plan', 6, 'func', 'Планирование по qemu-img measure', 'images - список пар [имя, вывод ''qemu-img measure'']. Вывод - строки ''required size: N'', ''fully allocated size: N'' и, не всегда, ''bitmaps size: N''. Напишите функцию plan_import(images, free, mode, unit): free - свободное место хранилища в байтах, mode - ''thin'' (берётся required size) или ''full'' (берётся fully allocated size), к размеру прибавляется bitmaps size (если строки нет - 0), затем размер округляется вверх до кратного unit. Образы обрабатываются по порядку: если размер не больше оставшегося места, образ принимается и место уменьшается, иначе он пропускается (последующие образы всё равно проверяются). Верните {''placed'': имена принятых, ''skipped'': имена пропущенных, ''free_left'': остаток места}.', 'def plan_import(images, free, mode, unit):
    pass
', 'Каждую строку вывода разберите регулярным выражением ''имя: число''; округление вверх - -(-x // unit) * unit.', '{"func": "plan_import", "tests": [{"args": [[["web1", "required size: 327680\nfully allocated size: 10742215680\n"], ["db1", "required size: 21475098624\nfully allocated size: 21476147200\nbitmaps size: 1048576\n"], ["win", "required size: 12884901888\nfully allocated size: 53687091200\n"], ["tiny", "required size: 196608\nfully allocated size: 1074003968\n"], ["cache", "required size: 1048577\nfully allocated size: 2097152\n"]], 21474836480, "thin", 1048576], "expected": {"placed": ["web1", "win", "tiny", "cache"], "skipped": ["db1"], "free_left": 8585740288}}, {"args": [[["web1", "required size: 327680\nfully allocated size: 10742215680\n"], ["db1", "required size: 21475098624\nfully allocated size: 21476147200\nbitmaps size: 1048576\n"], ["win", "required size: 12884901888\nfully allocated size: 53687091200\n"], ["tiny", "required size: 196608\nfully allocated size: 1074003968\n"], ["cache", "required size: 1048577\nfully allocated size: 2097152\n"]], 21474836480, "full", 1048576], "expected": {"placed": ["web1", "tiny", "cache"], "skipped": ["db1", "win"], "free_left": 9655287808}}, {"args": [[["web1", "required size: 327680\nfully allocated size: 10742215680\n"], ["db1", "required size: 21475098624\nfully allocated size: 21476147200\nbitmaps size: 1048576\n"], ["win", "required size: 12884901888\nfully allocated size: 53687091200\n"], ["tiny", "required size: 196608\nfully allocated size: 1074003968\n"], ["cache", "required size: 1048577\nfully allocated size: 2097152\n"]], 107374182400, "full", 1048576], "expected": {"placed": ["web1", "db1", "win", "tiny", "cache"], "skipped": [], "free_left": 20389560320}}, {"args": [[["web1", "required size: 327680\nfully allocated size: 10742215680\n"], ["db1", "required size: 21475098624\nfully allocated size: 21476147200\nbitmaps size: 1048576\n"], ["win", "required size: 12884901888\nfully allocated size: 53687091200\n"], ["tiny", "required size: 196608\nfully allocated size: 1074003968\n"], ["cache", "required size: 1048577\nfully allocated size: 2097152\n"]], 107374182400, "full", 536870912], "expected": {"placed": ["web1", "db1", "win", "tiny", "cache"], "skipped": [], "free_left": 18253611008}}, {"args": [[["web1", "required size: 327680\nfully allocated size: 10742215680\n"], ["db1", "required size: 21475098624\nfully allocated size: 21476147200\nbitmaps size: 1048576\n"], ["win", "required size: 12884901888\nfully allocated size: 53687091200\n"], ["tiny", "required size: 196608\nfully allocated size: 1074003968\n"], ["cache", "required size: 1048577\nfully allocated size: 2097152\n"]], 13958643712, "thin", 4194304], "expected": {"placed": ["web1", "win", "tiny", "cache"], "skipped": ["db1"], "free_left": 1061158912}}, {"args": [[["web1", "required size: 327680\nfully allocated size: 10742215680\n"], ["db1", "required size: 21475098624\nfully allocated size: 21476147200\nbitmaps size: 1048576\n"]], 22548578304, "thin", 1], "expected": {"placed": ["web1", "db1"], "skipped": [], "free_left": 1072103424}}, {"args": [[], 5, "thin", 1], "expected": {"placed": [], "skipped": [], "free_left": 5}}, {"args": [[["x", "required size: 1048577\nfully allocated size: 1048577\n"]], 2097152, "thin", 1048576], "expected": {"placed": ["x"], "skipped": [], "free_left": 0}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-loop-report', 7, 'func', 'Отчёт по losetup -a', 'text - вывод ''losetup -a''. Строка устройства: ''/dev/loopN: [устройство]:inode (файл)'', после device может стоять '' (lost)'' сразу за именем устройства, после '')'' могут идти '', offset N'' и '', sizelimit N''; без прав суперпользователя поля имеют вид ''[]:'' без чисел, а inode пуст. Если файл удалён, ядро дописывает к пути '' (deleted)''. Путь может содержать скобки и пробелы. Остальные строки игнорируйте. Напишите функцию loop_report(text, existing): existing - сколько узлов /dev/loop0..loop(existing-1) уже есть. Верните словарь: ''used'' - отсортированные номера занятых устройств; ''next'' - имя устройства с наименьшим свободным номером (то, что вернул бы ''losetup -f''); ''new'' - true, если этот номер не меньше existing (устройство придётся создать); ''duplicates'' - {файл: [устройства по возрастанию номера]} для файлов, подключённых к двум и более устройствам (путь без '' (deleted)''); ''deleted'' и ''lost'' - устройства с такими пометками, по возрастанию номера; ''offsets'' - {устройство: offset} только там, где offset больше нуля.', 'def loop_report(text, existing):
    pass
', 'Одно регулярное выражение на строку: номер, необязательный (lost), два числа в [], путь жадно до последней '')'' перед хвостом offset/sizelimit.', '{"func": "loop_report", "tests": [{"args": ["/dev/loop0: [64768]:131 (/var/lib/images/base.img)\n/dev/loop1: [64768]:140 (/var/lib/images/data.img), offset 1048576\n/dev/loop3: [2049]:77 (/tmp/old.img (deleted))\n/dev/loop4: [64768]:131 (/var/lib/images/base.img), sizelimit 536870912\n", 8], "expected": {"used": [0, 1, 3, 4], "next": "/dev/loop2", "new": false, "duplicates": {"/var/lib/images/base.img": ["/dev/loop0", "/dev/loop4"]}, "deleted": ["/dev/loop3"], "lost": [], "offsets": {"/dev/loop1": 1048576}}}, {"args": ["/dev/loop0: [64768]:131 (/var/lib/images/base.img)\n/dev/loop1: [64768]:140 (/var/lib/images/data.img), offset 1048576\n/dev/loop3: [2049]:77 (/tmp/old.img (deleted))\n/dev/loop4: [64768]:131 (/var/lib/images/base.img), sizelimit 536870912\n", 5], "expected": {"used": [0, 1, 3, 4], "next": "/dev/loop2", "new": false, "duplicates": {"/var/lib/images/base.img": ["/dev/loop0", "/dev/loop4"]}, "deleted": ["/dev/loop3"], "lost": [], "offsets": {"/dev/loop1": 1048576}}}, {"args": ["/dev/loop2: [0042]:12 (/srv/a.img), offset 32256, sizelimit 1000000\n/dev/loop0 (lost): [0042]:13 (/srv/b.img (deleted))\n/dev/loop1: []: (/srv/c (copy).img)\n", 3], "expected": {"used": [0, 1, 2], "next": "/dev/loop3", "new": true, "duplicates": {}, "deleted": ["/dev/loop0"], "lost": ["/dev/loop0"], "offsets": {"/dev/loop2": 32256}}}, {"args": ["", 8], "expected": {"used": [], "next": "/dev/loop0", "new": false, "duplicates": {}, "deleted": [], "lost": [], "offsets": {}}}, {"args": ["", 0], "expected": {"used": [], "next": "/dev/loop0", "new": true, "duplicates": {}, "deleted": [], "lost": [], "offsets": {}}}, {"args": ["/dev/loop0: [2049]:100 (/images/d0.img)\n/dev/loop1: [2049]:101 (/images/d1.img)\n/dev/loop2: [2049]:102 (/images/d2.img)\n/dev/loop3: [2049]:103 (/images/d3.img)\n/dev/loop4: [2049]:104 (/images/d4.img)\n/dev/loop5: [2049]:105 (/images/d5.img)\n/dev/loop6: [2049]:106 (/images/d6.img)\n/dev/loop7: [2049]:107 (/images/d7.img)\n", 8], "expected": {"used": [0, 1, 2, 3, 4, 5, 6, 7], "next": "/dev/loop8", "new": true, "duplicates": {}, "deleted": [], "lost": [], "offsets": {}}}, {"args": ["/dev/loop0: [2049]:100 (/images/d0.img)\n/dev/loop1: [2049]:101 (/images/d1.img)\n/dev/loop2: [2049]:102 (/images/d2.img)\n/dev/loop3: [2049]:103 (/images/d3.img)\n/dev/loop4: [2049]:104 (/images/d4.img)\n/dev/loop5: [2049]:105 (/images/d5.img)\n/dev/loop6: [2049]:106 (/images/d6.img)\n/dev/loop7: [2049]:107 (/images/d7.img)\n", 16], "expected": {"used": [0, 1, 2, 3, 4, 5, 6, 7], "next": "/dev/loop8", "new": false, "duplicates": {}, "deleted": [], "lost": [], "offsets": {}}}, {"args": ["/dev/loop5: [64768]:900 (/images/x.img)\n/dev/loop6: [64768]:900 (/images/x.img)\n/dev/loop7: [64768]:901 (/images/x.img), offset 0\nsnap: not a loop line\n", 8], "expected": {"used": [5, 6, 7], "next": "/dev/loop0", "new": false, "duplicates": {"/images/x.img": ["/dev/loop5", "/dev/loop6", "/dev/loop7"]}, "deleted": [], "lost": [], "offsets": {}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-sparse-report', 8, 'func', 'Разреженные файлы по stat', 'text - вывод одной или нескольких команд stat (GNU coreutils) подряд. Запись начинается строкой ''  File: имя'' (в старых версиях имя взято в кавычки ‘…’ или ''…'': снимите одну пару) и содержит строку ''  Size: N<табуляция>Blocks: B  IO Block: M  тип''; блоки по 512 байт (st_blocks). Учитывайте только записи с типом ''regular file'' или ''regular empty file''. Напишите функцию sparse_report(text): верните {''files'': список [имя, size, выделено в байтах (B*512), статус, экономия] по порядку, ''total_apparent'': сумма size, ''total_allocated'': сумма выделенного}. Статус: ''empty'', если size равен 0; ''hole'', если выделено 0 при size больше 0; ''sparse'', если выделено меньше size; иначе ''full''. Экономия - size минус выделено, но не меньше 0.', 'def sparse_report(text):
    pass
', 'Две регулярки: для ''File:'' и для строки ''Size: ... Blocks: ... IO Block: ... тип''; тип - остаток строки.', '{"func": "sparse_report", "tests": [{"args": ["  File: hole.img\n  Size: 10737418240\tBlocks: 0          IO Block: 4096   regular file\nDevice: fd00h/64768d\tInode: 131         Links: 1\nAccess: (0644/-rw-r--r--)  Uid: (    0/    root)   Gid: (    0/    root)\nAccess: 2026-11-03 14:00:00.000000000 +0000\nModify: 2026-11-03 14:00:00.000000000 +0000\nChange: 2026-11-03 14:00:00.000000000 +0000\n Birth: -\n  File: sparse.img\n  Size: 10737418240\tBlocks: 3568       IO Block: 4096   regular file\nDevice: fd00h/64768d\tInode: 131         Links: 1\nAccess: (0644/-rw-r--r--)  Uid: (    0/    root)   Gid: (    0/    root)\nAccess: 2026-11-03 14:00:00.000000000 +0000\nModify: 2026-11-03 14:00:00.000000000 +0000\nChange: 2026-11-03 14:00:00.000000000 +0000\n Birth: -\n  File: full.img\n  Size: 10737418240\tBlocks: 20971520   IO Block: 4096   regular file\nDevice: fd00h/64768d\tInode: 131         Links: 1\nAccess: (0644/-rw-r--r--)  Uid: (    0/    root)   Gid: (    0/    root)\nAccess: 2026-11-03 14:00:00.000000000 +0000\nModify: 2026-11-03 14:00:00.000000000 +0000\nChange: 2026-11-03 14:00:00.000000000 +0000\n Birth: -\n  File: note.txt\n  Size: 5\tBlocks: 8          IO Block: 4096   regular file\nDevice: fd00h/64768d\tInode: 131         Links: 1\nAccess: (0644/-rw-r--r--)  Uid: (    0/    root)   Gid: (    0/    root)\nAccess: 2026-11-03 14:00:00.000000000 +0000\nModify: 2026-11-03 14:00:00.000000000 +0000\nChange: 2026-11-03 14:00:00.000000000 +0000\n Birth: -\n"], "expected": {"files": [["hole.img", 10737418240, 0, "hole", 10737418240], ["sparse.img", 10737418240, 1826816, "sparse", 10735591424], ["full.img", 10737418240, 10737418240, "full", 0], ["note.txt", 5, 4096, "full", 0]], "total_apparent": 32212254725, "total_allocated": 10739249152}}, {"args": ["  File: empty\n  Size: 0\tBlocks: 0          IO Block: 4096   regular empty file\nDevice: fd00h/64768d\t