INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 19, 'la19-nfs-outages', 9, 'func', 'Простои NFS по журналу ядра', 'text - вывод ''journalctl -k -o short-iso'': строки ''2026-11-03T14:02:11+0000 host kernel: сообщение''. Интересны сообщения ''nfs: server ИМЯ not responding, still trying'', ''nfs: server ИМЯ not responding, timed out'' и ''nfs: server ИМЯ OK''; остальные строки игнорируйте. Простой сервера начинается с первого из двух сообщений ''not responding'' (при открытом простое повторные не открывают нового) и заканчивается ближайшим ''OK'' этого сервера; ''OK'' без открытого простоя игнорируется. Напишите функцию nfs_outages(text): верните словарь {сервер: {''outages'': [[начало, конец, секунды]], ''timeouts'': число сообщений ''timed out''}} только для серверов, у которых есть хотя бы один простой; начало и конец - строки времени как в журнале, секунды - целая разность во времени UTC (учитывайте смещение пояса); у незакрытого простоя конец и секунды равны None. Простои идут в порядке начала.', 'def nfs_outages(text):
    pass
', 'Один словарь открытых простоев по серверам; время разберите datetime.strptime(s, ''%Y-%m-%dT%H:%M:%S%z'').', '{"func": "nfs_outages", "tests": [{"args": ["2026-11-03T14:02:11+0000 vh1 kernel: nfs: server nfs1.example.com not responding, still trying\n2026-11-03T14:02:41+0000 vh1 kernel: nfs: server nfs1.example.com not responding, still trying\n2026-11-03T14:03:10+0000 vh1 kernel: nfs: server nfs1.example.com OK\n2026-11-03T14:10:00+0000 vh1 kernel: EXT4-fs (vda1): re-mounted. Opts: (null)\n2026-11-03T15:00:00+0000 vh1 kernel: nfs: server nfs1.example.com not responding, still trying\n2026-11-03T15:20:30+0000 vh1 kernel: nfs: server nfs1.example.com OK\n"], "expected": {"nfs1.example.com": {"outages": [["2026-11-03T14:02:11+0000", "2026-11-03T14:03:10+0000", 59], ["2026-11-03T15:00:00+0000", "2026-11-03T15:20:30+0000", 1230]], "timeouts": 0}}}, {"args": ["2026-11-03T10:00:00+0100 vh1 kernel: nfs: server nas2 OK\n2026-11-03T10:00:05+0100 vh1 kernel: nfs: server nas2 not responding, timed out\n2026-11-03T09:00:35+0000 vh1 kernel: nfs: server nas2 not responding, timed out\n2026-11-03T09:01:00+0000 vh1 kernel: nfs: server nfs1 not responding, still trying\n2026-11-03T10:02:00+0100 vh1 kernel: nfs: server nas2 OK\n2026-11-03T09:05:00+0000 vh1 kernel: nfs: server nfs1 OK\n2026-11-03T09:06:00+0000 vh1 kernel: nfs: server nfs1 not responding, still trying\n"], "expected": {"nas2": {"outages": [["2026-11-03T10:00:05+0100", "2026-11-03T10:02:00+0100", 115]], "timeouts": 2}, "nfs1": {"outages": [["2026-11-03T09:01:00+0000", "2026-11-03T09:05:00+0000", 240], ["2026-11-03T09:06:00+0000", null, null]], "timeouts": 0}}}, {"args": ["2026-11-03T10:00:00+0000 h1 kernel: nfs: server a not responding, still trying\n2026-11-03T10:00:30+0000 h1 kernel: nfs: server b not responding, still trying\n2026-11-03T10:01:00+0000 h1 kernel: nfs: server a OK\n2026-11-03T10:01:30+0000 h1 kernel: NFS: state manager: check lease failed on NFSv4 server b with error 11\n2026-11-03T10:02:00+0000 h1 kernel: nfs: server b OK\n-- Boot 1f3a --\n"], "expected": {"a": {"outages": [["2026-11-03T10:00:00+0000", "2026-11-03T10:01:00+0000", 60]], "timeouts": 0}, "b": {"outages": [["2026-11-03T10:00:30+0000", "2026-11-03T10:02:00+0000", 90]], "timeouts": 0}}}, {"args": [""], "expected": {}}, {"args": ["2026-11-03T14:02:11+0000 vh1 kernel: nfs: server nfs1.example.com not responding, still trying\n2026-11-03T14:02:41+0000 vh1 kernel: nfs: server nfs1.example.com not responding, still trying\n2026-11-03T14:03:10+0000 vh1 kernel: nfs: server nfs1.example.com OK\n2026-11-03T14:10:00+0000 vh1 kernel: EXT4-fs (vda1): re-mounted. Opts: (null)\n2026-11-03T15:00:00+0000 vh1 kernel: nfs: server nfs1.example.com not responding, still trying\n2026-11-03T15:20:30+0000 vh1 kernel: nfs: server nfs1.example.com OK\n2026-11-03T10:00:00+0000 h1 kernel: nfs: server a not responding, still trying\n2026-11-03T10:00:30+0000 h1 kernel: nfs: server b not responding, still trying\n2026-11-03T10:01:00+0000 h1 kernel: nfs: server a OK\n2026-11-03T10:01:30+0000 h1 kernel: NFS: state manager: check lease failed on NFSv4 server b with error 11\n2026-11-03T10:02:00+0000 h1 kernel: nfs: server b OK\n-- Boot 1f3a --\n"], "expected": {"nfs1.example.com": {"outages": [["2026-11-03T14:02:11+0000", "2026-11-03T14:03:10+0000", 59], ["2026-11-03T15:00:00+0000", "2026-11-03T15:20:30+0000", 1230]], "timeouts": 0}, "a": {"outages": [["2026-11-03T10:00:00+0000", "2026-11-03T10:01:00+0000", 60]], "timeouts": 0}, "b": {"outages": [["2026-11-03T10:00:30+0000", "2026-11-03T10:02:00+0000", 90]], "timeouts": 0}}}]}');
